function commandDependencies(form,kind,id,policyIDs=[],serviceID='',nodeIDs=[]){
 const targets=JSON.parse(form.dataset.targets),policies=JSON.parse(form.dataset.policies),result=[...targetDependencies(targets,kind,id)];
 if(serviceID)result.push(...targetDependencies(targets,'service',serviceID,true));
 for(const policyID of policyIDs){const policy=policies.find(v=>v.id===policyID);if(!policy)throw Error('Policy was not in the reviewed draft.');result.push(...targetDependencies(targets,'policy',policyID,true),...targetDependencies(targets,'service',policy.service_id,true))}
 const deviceDependencies=id=>{const row=JSON.parse(form.dataset.deviceDependencies||'[]').find(d=>d.id===id);if(!row?.dependencies?.length)throw Error('The reviewed node binding is unavailable.');return row.dependencies};
 if(kind==='device'&&!targets.some(t=>t.target_kind==='device'&&t.target_id===id))result.push(...deviceDependencies(id));
 for(const nodeID of nodeIDs)result.push(...(targets.some(t=>t.target_kind==='device'&&t.target_id===nodeID)?targetDependencies(targets,'device',nodeID,true):deviceDependencies(nodeID)));
 return [...new Set(result)].sort();
}

const app=document.querySelector('#app'),connection=document.querySelector('#connection'),notice=document.querySelector('#notice'),warningBox=document.querySelector('#evidence-warning');
let projection={ui_state:{warnings:[]},devices:[],links:[],paths:[],policies:[],services:[],releases:[],},reports=[],admin=false,operations=new Set,lastSnapshot='',enrollmentOptions=null,deferredRender=false,snapshotSerial=0;
const inviteCache=new Map,inviteLoads=new Set;
const histories=new Map,historyLoads=new Map;
let evidenceTimer=0,evidenceUTC=Date.now(),evidenceMonotonic=performance.now();
function evidenceNow(){const tick=performance.now();evidenceUTC=Math.max(Date.now(),evidenceUTC+tick-evidenceMonotonic);evidenceMonotonic=tick;return evidenceUTC}
function updateDisplayedEvidence(){projection=expireEvidence(projection,evidenceNow());reports=list(projection.devices).filter(v=>v.evidence).map(v=>({device_id:v.id,...v.evidence,observations:list(v.evidence.measurements)}))}
function scheduleEvidenceExpiry(){clearTimeout(evidenceTimer);const now=evidenceNow(),times=[nextEvidenceExpiry(projection,now),trafficNextExpiry(histories,now)].filter(v=>v>now),until=times.length?Math.min(...times):0;if(!until)return;evidenceTimer=setTimeout(()=>{updateDisplayedEvidence();stableRender();scheduleEvidenceExpiry()},Math.max(1,Math.min(2147483647,until-now+1)))}
const list=v=>Array.isArray(v)?v:[],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=v=>String(v||'').replace(/^sha256:/,'').slice(0,12)||'—',validState=v=>['available','unavailable','unknown'].includes(v)?v:'unknown',badge=v=>`<span class="badge ${esc(validState(v))}">${esc(v||'unknown')}</span>`,when=v=>v?new Date(v).toLocaleString():'—';
const heading=(title,lead,actions='',eyebrow='LOOM CONTROL')=>`<div class="heading network-heading"><div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(lead)}</p></div>${actions}</div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No projected records.</td></tr>`}</tbody></table></div>`;
async function api(path,options={}){const response=await fetch(path,{headers:{Accept:'application/json',...(options.headers||{})},...options});if(!response.ok)throw Error((await response.text()).trim()||`HTTP ${response.status}`);return response.json()}
function toast(message,error=false){notice.textContent=message;notice.className=error?'error':'';notice.hidden=false;setTimeout(()=>notice.hidden=true,5000)}
function accept(payload,redraw=true){
 if(payload?.schema!==3)throw Error('Unsupported control snapshot.');
 snapshotSerial++;
 projection={...payload,ui_state:{...payload.ui_state,writable:!!payload.ui_state?.local_writable,warnings:list(payload.ui_state?.warnings).map(v=>v.message)}};
 // A new server-qualified projection can recover after the local clock is
 // corrected. Between projections, monotonic elapsed time still prevents renewal.
 evidenceUTC=Date.now();evidenceMonotonic=performance.now();
 updateDisplayedEvidence();scheduleEvidenceExpiry();
 admin=!!payload.capabilities?.admin;operations=new Set(list(payload.capabilities?.operations));
 const messages=list(projection.ui_state.warnings);warningBox.hidden=!messages.length;warningBox.textContent=messages.join(' ');
 const credential=payload.capabilities?.credential;connection.textContent=projection.ui_state.writable?(credential==='local_admin'?'Local admin view':'Admin view'):'Admin · read only';connection.title=`${projection.ui_state.writable?'local writes available':'read only'} · config ${payload.control_config_id}`;document.querySelector('#current-control').textContent=list(payload.devices).find(v=>v.id===payload.local_node_id)?.name||payload.local_node_id||'';
 connection.className='ok';deferredRender=!redraw;if(redraw)stableRender();
}
// Only coordinate in-flight UI requests; this counter does not order authority facts.
async function refresh(redraw=true){const started=snapshotSerial,payload=await api('/api/control/ui/snapshot');if(started!==snapshotSerial)return;const encoded=JSON.stringify(payload);if(encoded!==lastSnapshot){lastSnapshot=encoded;accept(payload,redraw)}}
const warnings=()=>'';
const canOperate=kind=>admin&&operations.has(kind);
const domKey=node=>node.nodeType===1&&(node.getAttribute('id')||node.dataset?.key||node.dataset?.eventId||node.getAttribute('name')||'');
function morphNode(current,next){if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){current.replaceWith(next.cloneNode(true));return}if(current.nodeType===Node.TEXT_NODE){if(current.data!==next.data)current.data=next.data;return}if(current.matches?.('form[data-request-id]')){if(current.dataset.deviceId!==next.dataset.deviceId||current.dataset.replaceId!==next.dataset.replaceId)current.replaceWith(next.cloneNode(true));return;}const keepOpen=current.matches?.('details[open]');for(const attribute of [...current.attributes])if(!next.hasAttribute(attribute.name))current.removeAttribute(attribute.name);for(const attribute of [...next.attributes])if(current.getAttribute(attribute.name)!==attribute.value)current.setAttribute(attribute.name,attribute.value);if(keepOpen)current.open=true;morphChildren(current,next)}
function morphChildren(current,next){const keyed=new Map([...current.childNodes].map(node=>[domKey(node),node]).filter(([key])=>key)),used=new Set;let cursor=current.firstChild;for(const wanted of [...next.childNodes]){const key=domKey(wanted);let node=key&&keyed.get(key);if(node&&used.has(node))node=null;if(!node&&cursor&&!used.has(cursor)&&!domKey(cursor)&&cursor.nodeType===wanted.nodeType&&cursor.nodeName===wanted.nodeName)node=cursor;if(!node){node=wanted.cloneNode(true);current.insertBefore(node,cursor)}else{used.add(node);if(node!==cursor)current.insertBefore(node,cursor);morphNode(node,wanted)}cursor=node.nextSibling}while(cursor){const following=cursor.nextSibling;current.removeChild(cursor);cursor=following}}
function stableRender(){const root=document.scrollingElement,scroll=[root.scrollLeft,root.scrollTop],active=document.activeElement&&document.activeElement!==document.body?{node:document.activeElement,start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null,oldChildren=[...app.childNodes],oldClass=app.className,locks=[...document.querySelectorAll('#topology,.overview-topology-card')].map(v=>v.dataset.locked||'');render();const next=app.cloneNode(true),nextClass=app.className;app.replaceChildren(...oldChildren);app.className=oldClass;morphChildren(app,next);app.className=nextClass;document.querySelectorAll('#topology,.overview-topology-card').forEach((v,i)=>v.dataset.locked=locks[i]||'');queueMicrotask(()=>{if(active?.node?.isConnected){active.node.focus({preventScroll:true});if(typeof active.node.setSelectionRange==='function'&&active.start!=null)active.node.setSelectionRange(active.start,active.end)}scrollTo(scroll[0],scroll[1])})}

function pathLabel(path){if(path.final_exit==='direct')return `${path.device} → target (Direct)`;if(!list(path.chain).length)return `${path.device} (local egress: ${path.final_exit}) → target`;return [path.device,...list(path.chain),'target'].join(' → ')}
function currentSelection(path){return path.selected&&reportIsCurrent(list(projection.devices).find(v=>v.id===path.device)?.evidence,evidenceNow())}
const runtimeBadge=state=>`<span class="badge ${state==='running'?'available':state==='error'?'unavailable':'unknown'}">${esc(state)}</span>`;
const runtimeSummary=counts=>[`${counts.running} running`,...['error','stopped','unknown'].filter(state=>counts[state]).map(state=>`${counts[state]} ${state}`)].join(' · ');
const runtimeIndicator=counts=>`<span class="status-check ${counts.error?'bad':counts.running?'':'unknown'}">${counts.error?'!':counts.running?'✓':'?'}</span>`;
function nodeServiceReadbacks(device){
 const paths=list(projection.paths).filter(path=>path.device===device.id),ids=[...new Set(paths.map(path=>path.service_id))].sort();
 return ids.map(id=>{const selected=paths.filter(path=>path.service_id===id&&currentSelection(path)),service=list(projection.services).find(value=>value.id===id),query=new URLSearchParams({service:id,device:device.id});return `<small data-node-service="${esc(id)}"><a href="/routing?${esc(query)}" data-nav>${esc(service?.name||id)}</a>: ${badge(selected.length===1?selected[0].availability:'unknown')}</small>`}).join('');
}

function topology(compact=false,options={}){
 const params=new URLSearchParams(location.search),devices=currentDevices(projection),serviceID=options.serviceID??params.get('service')??list(projection.services)[0]?.id??'',showWG=options.showWG??(params.get('wg')!=='0'),showHy2=options.showHy2??(params.get('hy2')!=='0'),showRoute=options.showRoute??(params.get('route')!=='0');
 const paths=list(projection.paths).filter(path=>path.service_id===serviceID),selected=paths.filter(currentSelection),links=options.links||list(projection.links).filter(link=>link.transport==='wireguard'?showWG:showHy2);
 const firstHops=new Map();
 for(const chosen of selected){
  for(const path of paths){
   if(path.device!==chosen.device||!path.first_resource_id||!path.chain.length||path.chain[0]!==chosen.chain[0]||path.chain[0]===path.device)continue;
   if(path.first_transport==='wireguard'?!showWG:!showHy2)continue;
   const device=devices.find(v=>v.id===path.device),samples=list(device?.evidence?.measurements).filter(sample=>sample.level==='resource'&&sample.resource_id===path.first_resource_id&&sample.current_until>evidenceNow());
   firstHops.set(path.device+'\0'+path.first_resource_id,{From:path.device,To:path.chain[0],Transport:path.first_transport,Kind:'first_hop',State:samples.length===1?samples[0].result:'unknown',ResourceID:path.first_resource_id});
  }
 }
 const view={Nodes:devices.map(device=>({ID:device.id,Name:device.name,Roles:device.roles,Runtime:nodeRuntimeState(device,evidenceNow()),Location:device.location||''})),SelectedLink:compact?'':options.selectedLink||params.get('link')||'',SelectedServiceName:selected.some(path=>list(path.link_ids).includes(options.selectedLink||params.get('link')))?list(projection.services).find(service=>service.id===serviceID)?.name||serviceID:'',ShowWG:showWG,ShowHy2:showHy2,Links:[...links.map(link=>({ID:link.id,Metrics:[...linkRoundTripMetrics(projection,link,histories.get('link:'+link.id),evidenceNow()).map(value=>value.text),...trafficRates(trafficScope('link:'+link.id),evidenceNow()).map(value=>value.text)],From:link.from,To:link.to,Transport:link.transport,Kind:'tunnel',State:validState(link.availability)})),...firstHops.values()]};
 const routes=showRoute?selected.map(path=>({Chain:path.chain[0]===path.device?list(path.chain):[path.device,...list(path.chain)],FirstTransport:path.chain[0]===path.device?'':path.first_transport})):[];
 return topologyHTML(view,routes,compact?'overview-topology':'network');
}

const byteSize=trafficBytes;
const age=value=>{if(!value)return'—';const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return`${seconds}s`;if(seconds<3600)return`${Math.floor(seconds/60)}m`;if(seconds<86400)return`${Math.floor(seconds/3600)}h`;return`${Math.floor(seconds/86400)}d`};
