 const label={unavailable:'Expectation unavailable',unconfigured:'No expectation set',missing:'No component readback',unknown:'Digest unavailable',reported_match:'Reported coordinates match',reported_mismatch:'Reported coordinates differ'};
 return componentComparisons(device,report).map(row=>`<tr data-component="${esc(row.component_id)}" data-platform="${esc(row.platform)}"><td>${esc(row.component_id)}<small>${esc(row.platform)}</small></td><td>${row.expected?coordinate(row.expected):'Not set'}</td><td>${coordinate(row.actual)}</td><td><span class="${row.result==='reported_mismatch'?'bad':'dim'}">${label[row.result]}</span><small>${reportIsCurrent(report,evidenceNow())?'Current report':'Historical report'} · ${esc(when(report?.reported_at))}</small></td></tr>`).join('');
