let overviewEvents=null,overviewEventsLoading=null;
function overviewEventKey(){return projection.network_id+'\0'+projection.control_config_id}
async function loadOverviewEvents(){
 if(location.pathname!=='/'||overviewEventsLoading||overviewEvents?.key===overviewEventKey())return;
 const key=overviewEventKey(),controller=new AbortController;overviewEventsLoading=controller;
 const until=evidenceNow(),query=new URLSearchParams({from:new Date(until-3600000).toISOString(),until:new Date(until).toISOString()});
 try{const data=await api('/api/control/ui/events?'+query,{signal:controller.signal});if(location.pathname==='/'&&key===overviewEventKey())overviewEvents={key,data}}
 catch(error){if(error.name!=='AbortError'&&location.pathname==='/'&&key===overviewEventKey())overviewEvents={key,error:error.message}}
 finally{if(overviewEventsLoading===controller){overviewEventsLoading=null;if(location.pathname==='/')stableRender()}}
}
