 const pathRows=list(projection.services).map(service=>{const chosen=selected.filter(path=>path.device===focused?.id&&path.service_id===service.id),value=chosen.length===1?chosen[0]:null,target=list(projection.targets).find(target=>target.target_kind==='service'&&target.target_id===service.id),query=new URLSearchParams({service:service.id,...(focused?{device:focused.id}:{})});return `<tr><td><a class="mono" href="/routing?${esc(query)}" data-nav>${esc(service.name||service.id)}</a></td><td title="${esc(value?pathLabel(value):'No current signed selection')}">${value?value.final_exit==='direct'?'Direct':`via ${esc(devices.find(device=>device.id===value.final_exit)?.name||value.final_exit)}`:paths.some(path=>path.device===focused?.id&&path.service_id===service.id)?'none · no current selection':'none · no grant'}</td><td>${badge(value?.availability||'unknown')}</td><td>${target?.conflicted?'conflict':target?.deleted?'removed':'effective'}</td></tr>`}).join('');
 const wanted=[...new Set(configured.flatMap(device=>device.expected_components.map(component=>component.component_id)))].sort(),catalog=list(projection.releases),facts=list(projection.fact_frontier),eventData=overviewEvents?.key===overviewEventKey()?overviewEvents:null,eventRows=list(eventData?.data?.events).slice(0,3).map(event=>`<a class="overview-event-item" href="/events?object=${encodeURIComponent(event.subject)}" data-nav title="Received ${esc(when(event.at))} · ${esc(event.source)}"><i class="event-dot ${event.kind==='conflict'?'problem':event.kind==='runtime'?'pending':''}"></i>${esc(event.detail||event.subject)}</a>`).join('');
