function sshReason(code){return ({ssh_executor_unavailable:'SSH execution is not configured on this control.',verified_installer_unavailable:'A verified public installer could not be read.',target_inspection_invalid:'The target did not return a valid installation inspection.',existing_device_identity:'The target already has a device identity.',existing_installation_unverified:'The existing installation requires a verified forward migration.',enrollment_identity_differs:'The target identity belongs to another invitation or network.',enrollment_identity_missing:'The original bound identity is missing; it cannot be recreated.',enrollment_not_executable:'This invitation is not available for execution on this control.',enrollment_binding_differs:'The target key or original request differs from the accepted binding.',device_no_longer_authorized:'This device is no longer authorized.',connection_interrupted:'The SSH connection was interrupted. The remote result is unknown.',connection_unconfirmed:'SSH could not confirm the remote result. Check connectivity, credentials and the pinned host key.',readback_exceeds_limit:'The target output exceeded the inspection limit; the result is unknown.',executor_unavailable:'The local SSH command could not start.',target_requires_linux:'The target reported an unsupported operating system; Linux is required.',target_architecture_unsupported:'The target reported an unsupported CPU architecture.',target_package_unavailable:'The target could not obtain a verified package for its architecture.',target_tool_missing:'The target is missing a required installation tool.',target_privilege_required:'The target requires root or passwordless sudo.',target_installer_unavailable:'The target could not download and verify the installer.',target_installation_running:'Another installation is still running on the target.',target_enrollment_incomplete:'Joining is incomplete; runtime activation was withheld.',target_runtime_unconfirmed:'The installer could not confirm the exact running service.',target_command_failed:'The remote command reported failure.',existing_trust_differs:'The existing installation trust differs from the selected package.',existing_trust_unavailable:'The existing installation trust cannot be read safely.',existing_package_unverified:'The existing accepted package could not be verified.',package_would_rollback_or_equivocate:'This package would roll back or replace different bytes in the accepted generation.'})[code]||'The target could not be checked. The current invitation and identity are preserved.'}
