 if(device){app.innerHTML=heading('Device invitation',esc(device.name||device.id))+deviceInvite(device,true)+`<div class="device-form-footer"><a class="button primary" href="/devices/${encodeURIComponent(device.id)}" data-nav>Continue in device details</a></div>`;return}
