function servicesPage(){
 if(new URLSearchParams(location.search).get('tab')==='dns'){dnsPage();return}
 const all=list(projection.services).sort((a,b)=>(a.name||a.id).localeCompare(b.name||b.id)),params=new URLSearchParams(location.search),creating=params.get('new')==='1',value=creating?{id:'',name:'',kind:params.get('kind')==='local_network'?'local_network':'internet',matchers:[]}:params.has('service')?all.find(v=>v.id===params.get('service')):all[0];
 app.className='network-page page-services';
 const catalog=all.map(v=>`<a class="service-item ${v.id===value?.id?'selected':''}" href="/services?service=${encodeURIComponent(v.id)}" data-nav><b>${esc(v.name||v.id)}</b><small>${v.kind==='local_network'?`LAN · ${esc(v.local_network.virtual_prefix)}`:`Internet · ${list(v.matchers).length} rules`}</small></a>`).join('');
 const related=list(projection.policies).filter(v=>v.service_id===value?.id);
 const editor=value?`<section class="service-editor"><div class="sectionhead"><h2>${creating?'New Service':'Service details'}</h2><span class="tiny dim">${value.id?'Service ID · '+esc(value.id):'New draft'}</span></div><form id="service-form" data-service="${esc(JSON.stringify(value))}" ${draftAttributes()}><div class="service-identity" ${value.id?'data-existing-identity':''}>${value.id?`<input type="hidden" name="id" value="${esc(value.id)}">`:`<div class="field"><label>SERVICE ID</label><input name="id" required></div>`}<div class="field"><label>DISPLAY NAME</label><input name="name" required value="${esc(value.name)}"></div></div><div class="field service-kind" ${creating?'':'hidden'}><label>Service kind</label><select name="kind" ${creating?'':'disabled'}><option value="internet" ${value.kind==='internet'?'selected':''}>Internet</option><option value="local_network" ${value.kind==='local_network'?'selected':''}>Local network</option></select></div><section data-internet-fields ${value.kind==='local_network'?'hidden':''}><section class="service-destinations"><div class="sectionhead"><h3>Destinations</h3><span data-matcher-count class="tiny dim">${list(value.matchers).length} matchers</span></div><div class="matcher-head"><span>HOSTNAME OR SUFFIX</span><span>MATCH</span></div><div data-service-matchers>${(list(value.matchers).length?list(value.matchers):[{kind:'dns_exact',value:''}]).map(matcherRowHTML).join('')}</div><button type="button" data-matcher-add>＋ Add matcher</button><textarea name="matchers" hidden>${esc(list(value.matchers).map(v=>v.kind+' '+v.value).join('\n'))}</textarea><small>A suffix starts with a dot; the saved canonical value omits this display prefix.</small></section></section>${lanServiceFields(value,creating,params.get('gateway'))}<section class="service-probes"><h3>Matching authorised probe targets</h3>${[...new Set(list(projection.paths).filter(path=>path.service_id===value.id).flatMap(path=>list(path.targets)))].sort().map(target=>`<p class="mono">${esc(target)}</p>`).join('')||'<p class="dim">No target known for current authorised device views.</p>'}<small>Known device views only · filtered by this Service and each device’s Policy.</small></section><section class="service-related"><h3>Policies for this Service</h3>${value.id&&canOperate('policy.put')?`<a class="button" href="/policies?new=1&service=${encodeURIComponent(value.id)}" data-nav>New Policy for this Service</a>`:''}${related.map(p=>`<p><a href="/policies?policy=${encodeURIComponent(p.id)}" data-nav>${esc(p.name||p.id)}</a> · ${esc(p.action)}</p>`).join('')||'<p class="dim">No Policy selects this Service yet.</p>'}${!creating?policyImpact(related.map(p=>p.id)):''}</section><div class="service-save"><span id="operation-status" role="alert"></span><button class="primary" type="submit" form="service-form" ${canOperate('service.put')?'':'disabled'}>Save Service</button>${value.id&&canOperate('service.delete')?`<button type="button" class="danger" data-delete-kind="service" data-delete-id="${esc(value.id)}">Delete</button>`:''}</div></form></section>`:`<section class="service-editor"><p class="empty">${params.has('service')?'This Service is unavailable. No other Service has been opened.':'No Service has been created.'}</p>${list(projection.targets).some(t=>t.target_kind==='service'&&t.target_id===params.get('service')&&t.conflicted)?'<a href="/ssot?section=configuration" data-nav>Review the current conflict →</a>':''}</section>`;
 app.innerHTML=heading('Services','Define the targets that policies can authorize.',canOperate('service.put')?'<a class="button primary" href="/services?new=1" data-nav>＋ Add service</a>':'','NETWORK INTENT')+`<div class="service-tabs"><a class="selected" href="/services" data-nav>Services</a><a href="/services?tab=dns" data-nav>Exact .loom DNS</a><a href="/policies" data-nav>Policies</a></div><div class="services-layout"><aside class="service-catalog"><div class="sectionhead"><h2>All services</h2><span>${all.length}</span></div><input type="search" data-catalog-search aria-label="Search service or destination" placeholder="Search name or destination">${catalog||'<p class="empty">No services.</p>'}${list(projection.targets).filter(t=>t.target_kind==='service'&&t.conflicted).map(t=>`<a class="service-item" href="/ssot?section=configuration&target=${encodeURIComponent(t.target_id)}" data-nav><b>${esc(t.target_id)}</b><small>Suspended · review conflict →</small></a>`).join('')}</aside>${editor}</div>`;
 const form=document.querySelector('#service-form');if(form)updateLANForm(form);
}
